// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX4} from "../src/MultiplicatorX4.sol";

contract InvMutTest is Test {
    MultiplicatorX4 c;
    function setUp() public { c = new MultiplicatorX4(); }
    function testFuzz_property(bytes memory data, uint256 amount) public {
        amount = bound(amount, 0, 1000 ether);
        Receiver recv = new Receiver();
        address target = address(recv);
        address owner = c.Owner();
        vm.deal(owner, amount * 2);
        uint256 balBefore = target.balance;
        vm.prank(owner);
        (bool success, ) = address(c).call{value: amount}(abi.encodeWithSignature("Command(address,bytes)", target, data));
        if(success) {
            assertEq(target.balance, balBefore + amount);
        }
    }
}

contract Receiver {
    fallback() external payable {}
}
